This is a greedy simulation with a small local-search-free scoring rule, so it runs fast and is deterministic.

**Approach:**
- Process vehicles by their free time using a min-heap, so the vehicle that becomes free earliest picks next.
- For the chosen vehicle, scan all unassigned rides and compute the arrival time at the ride's start, `arr = t + dist(pos, start)`, and the actual start time `st = max(arr, s)`. The ride is feasible only if `st + d <= f`.
- Score each feasible ride as `d + (st == s ? B : 0)`, minus the time cost `(finish_time - t)`. The score is `(d + bonus) / (finish_time - t)`, a points-per-time rate. Compare candidates as fractions with cross-multiplication in 64-bit integers.
- If a vehicle has no feasible ride, it is retired.
- Complexity is O(F·N) per round in the worst case: each assignment scans N rides, and there are at most N assignments in total, so about 10^4 × 10^4 = 10^8 operations. This is fine.
- To make the scan cheaper, I keep a compact list of unassigned rides and remove a ride by swapping it with the last element.

**Rate details:** the denominator is `finish - t`, which includes the travel and wait time plus the ride distance, and it is always at least 1 because the ride distance is at least 1. Comparison is `(num1 * den2 > num2 * den1)`. Ties are broken by the lower ride index, since the scan order is deterministic after swap-removal.

**Heap details:** the heap holds `(time, vehicle)` pairs. After a vehicle is assigned a ride, it is pushed back with its finish time. Rides that finish after `T` cannot satisfy `f <= T`, so they are excluded by the feasibility check.

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int R,C,F,N;ll B,T;
    scanf("%d %d %d %d %lld %lld",&R,&C,&F,&N,&B,&T);
    vector<int> a(N),b(N),x(N),y(N);vector<ll> s(N),f(N);
    for(int i=0;i<N;i++){
        scanf("%d %d %d %d %lld %lld",&a[i],&b[i],&x[i],&y[i],&s[i],&f[i]);
    }
    vector<int> rem(N);
    for(int i=0;i<N;i++)rem[i]=i;
    vector<int> px(F,0),py(F,0);
    vector<vector<int>> res(F);
    priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>> pq;
    for(int i=0;i<F;i++)pq.push({0,i});
    while(!pq.empty()&&!rem.empty()){
        auto [t,v]=pq.top();pq.pop();
        ll bn=-1,bd=1;int bi=-1;
        for(int k=0;k<(int)rem.size();k++){
            int r=rem[k];
            ll d=abs(x[r]-a[r])+abs(y[r]-b[r]);
            ll arr=t+abs(px[v]-a[r])+abs(py[v]-b[r]);
            ll st=max(arr,s[r]);
            ll fin=st+d;
            if(fin>f[r])continue;
            ll num=d+(st==s[r]?B:0);
            ll den=fin-t;
            if(bi<0||num*bd>bn*den){bn=num;bd=den;bi=k;}
        }
        if(bi<0)continue;
        int r=rem[bi];
        ll d=abs(x[r]-a[r])+abs(y[r]-b[r]);
        ll arr=t+abs(px[v]-a[r])+abs(py[v]-b[r]);
        ll st=max(arr,s[r]);
        res[v].push_back(r);
        px[v]=x[r];py[v]=y[r];
        pq.push({st+d,v});
        rem[bi]=rem.back();rem.pop_back();
    }
    for(int i=0;i<F;i++){
        printf("%d",(int)res[i].size());
        for(int r:res[i])printf(" %d",r);
        printf("\n");
    }
}
```
